    h, w = len(grid), len(grid[0])
    transitions = Counter()
    colors = set()

    # Interior cells contain the repeating pattern; the outer frame is decorative.
    for r in range(3, h):
        for c in range(3, w):
            v = grid[r][c]
            if v:
                colors.add(v)
            if c + 1 < w and v and grid[r][c + 1]:
                transitions[(v, grid[r][c + 1])] += 1

    # Recover the repeating color order from the most frequent horizontal transitions.
    successor = {}
    for a in colors:
        options = [(count, b) for (x, b), count in transitions.items() if x == a]
        if options:
            successor[a] = max(options)[1]

    start = max(colors, key=lambda a: sum(transitions[(a, b)] for b in colors))
    palette = [start]
    while len(palette) < len(colors):
        nxt = successor.get(palette[-1])
        if nxt is None or nxt in palette:
            break
        palette.append(nxt)

    # If a rare anomalous color prevented cycle recovery, retain only the main cycle.
    if len(palette) != len(colors):
        while palette and successor.get(palette[-1]) not in palette:
            palette.pop()
        if not palette:
            palette = sorted(colors)

    index = {v: i for i, v in enumerate(palette)}
    phases = Counter()
    for r in range(3, h):
        for c in range(3, w):
            v = grid[r][c]
            if v in index:
                phases[(index[v] - r - c) % len(palette)] += 1
    phase = phases.most_common(1)[0][0]

    out = [row[:] for row in grid]
