def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    # The repeating pattern occupies the interior; use its undamaged lower-right
    # portion to recover the color cycle and its phase.
    region = [(r, c, grid[r][c])
              for r in range(8, h) for c in range(3, w)
              if grid[r][c] != 0]
    colors = {v for _, _, v in region}

    edges = Counter()
    for r in range(8, h):
        for c in range(3, w - 1):
            a, b = grid[r][c], grid[r][c + 1]
            if a and b:
                edges[a, b] += 1

    successor = {}
    for a in colors:
        choices = [(count, b) for (x, b), count in edges.items() if x == a]
        if choices:
            successor[a] = max(choices)[1]

    # Start anywhere in the cycle; the phase calculation below compensates
    # for the arbitrary rotation.
    start = next(iter(colors))
    palette = [start]
    while successor.get(palette[-1]) not in palette and len(palette) < len(colors):
        nxt = successor.get(palette[-1])
        if nxt is None:
            break
        palette.append(nxt)

    # In case the first region cell is an exceptional color, use the largest
    # transition cycle found among the observed colors.
    if len(palette) < len(colors):
        candidates = []
        for s in colors:
            seq = [s]
            while successor.get(seq[-1]) not in seq and len(seq) <= len(colors):
                nxt = successor.get(seq[-1])
                if nxt is None:
                    break
                seq.append(nxt)
            candidates.append(seq)
        palette = max(candidates, key=len)

    n = len(palette)
    idx = {v: i for i, v in enumerate(palette)}
    phase_votes = Counter()
    for r, c, v in region:
        if v in idx:
            phase_votes[(idx[v] - r - c) % n] += 1
    phase = phase_votes.most_common(1)[0][0]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = palette[(r + c + phase) % n]
    return out
